{"code": "import pandas as pd

df = pd.read_csv('/home/musel/Github/research_agent/data/trial.csv')

# Check for -999.0 in biomarker_baseline
missing_count = (df['biomarker_baseline'] == -999.0).sum()
print(f'Number of rows with biomarker_baseline = -999.0: {missing_count}')

# Check if any other columns have sentinel values
sentinel_cols = ['biomarker_final', 'age', 'sex', 'assay_batch', 'responded']
for col in sentinel_cols:
    if df[col].dtype == 'object':
        # For string columns, check for 'NA', 'null', etc.
        missing = df[col].isin(['NA', 'NULL', 'nan', 'N/A', '']).sum()
        if missing > 0:
            print(f'{col}: {missing} missing-like values')
    else:
        # For numeric columns, check for -999.0
        missing = (df[col] == -999.0).sum()
        if missing > 0:
            print(f'{col}: {missing} values == -999.0')"}
